"""Write Experiment 3's appendix from the stored sweeps and per-participant scores.

Five kinds of table. The two sweeps, pooled agreement and balanced accuracy, at every count
from three to twenty on both arms. The occupancy rule that decides which counts are
selectable at all, with the midpoint share beside it. The selection and its jackknife. Then
the folds themselves, one table per slice, so a reader can see which visitor produced an
extreme.

    python3 -u -m scripts.exp1_v2.make_exp3_appendix
"""
import re

import numpy as np
import pandas as pd

def spanhead(n, labels):
    """Spanning header cells: a rule to the right of each, the outer edge after the last."""
    cells = [f"\\multicolumn{{{n}}}{{c!{{\\colsepline}}}}{{{lab}}}" for lab in labels]
    cells[-1] = cells[-1].replace("!{\\colsepline}", "!{\\tabedge}")
    return " & ".join(cells)


def bordered(spec):
    """House column spec: outer \\tabedge rules and a \\colsepline between every column."""
    cols = [c for c in spec if c in "lcr"]
    return "!{\\tabedge}" + "!{\\colsepline}".join(cols) + "!{\\tabedge}"

from scripts.exp1_v2.selection import OUT

OUT_DIR = OUT / "exp3"
TEX = "/Users/akshaj/Documents/Thesis/research-proposal/appendix_final_exp3.tex"

SLICES = [("rcea", "valence"), ("rcea", "arousal"),
          ("retro", "valence"), ("retro", "arousal")]
COUNTS = list(range(3, 21))
SELECTABLE = (3, 4, 5, 6, 7)


def sweep_rows(metric):
    """One row per level count, the two arms side by side in every slice."""
    post = pd.read_csv(OUT_DIR / "sweep_posthoc.csv")
    trained = pd.read_csv(OUT_DIR / "sweep_trained.csv")
    rows, prev = [], None
    for B in COUNTS:
        sel = B in SELECTABLE
        if prev is not None and sel != prev:
            rows.append("\\groupsep")
        elif prev is not None:
            rows.append("\\rowsep")
        cells = []
        for st, ax in SLICES:
            for d in (trained, post):
                h = d[(d.stream == st) & (d.axis == ax) & (d.B == B)][metric]
                cells.append(f"${h.iloc[0]:+.4f}$" if len(h) else "")
        mark = "" if sel else "$^{\\dagger}$"
        rows.append(f"{B}{mark} & " + " & ".join(cells) + r" \\")
        prev = sel
    return "\n".join(rows)


def occupancy_rows():
    occ = pd.read_csv(OUT_DIR / "occupancy.csv")
    rows, prev = [], None
    for B in COUNTS:
        sel = B in SELECTABLE
        if prev is not None and sel != prev:
            rows.append("\\groupsep")
        elif prev is not None:
            rows.append("\\rowsep")
        cells = []
        for st, ax in SLICES:
            h = occ[(occ.stream == st) & (occ.axis == ax) & (occ.B == B)]
            cells.append(f"${100 * h.min_share.iloc[0]:.2f}$" if len(h) else "")
        g = occ[occ.B == B]
        edge = "on a boundary" if bool(g.midpoint_on_edge.iloc[0]) else "inside a level"
        rows.append(f"{B} & " + " & ".join(cells) + f" & {edge} & "
                    + ("yes" if sel else "no") + r" \\")
        prev = sel
    return "\n".join(rows)


def selection_rows():
    s = pd.read_csv(OUT_DIR / "selection.csv")
    rows = []
    for st, ax in SLICES:
        h = s[(s.stream == st) & (s.axis == ax)]
        if h.empty:
            continue
        r = h.iloc[0]
        rows.append(f"{st} {ax} & {int(r.best_count)} & ${r.best_qwk:+.4f}$ & "
                    f"${r.span:.4f}$ & {r.tied_counts} & {int(r.carried_count)} & "
                    f"{int(r.jackknife_winner)} & {int(r.jackknife_stable)}/"
                    f"{int(r.jackknife_folds)} & ${r.jackknife_pct:.0f}\\%$" + r" \\")
    return "\n\\rowsep\n".join(rows)


def summary_rows():
    """Per-visitor agreement summarised at every selectable count, on both arms.

    The sweep tables above give the pooled figure, which is one number over every held-out
    prediction at once. This gives the spread across visitors behind it, which the pooled
    figure cannot show and which Section~\\ref{sec:results-exp3-pooling} turns on.
    """
    frames = []
    for arm in ("trained", "posthoc"):
        f = OUT_DIR / f"sweep_{arm}_perfold.csv"
        if f.is_file():
            frames.append(pd.read_csv(f))
    d = pd.concat(frames, ignore_index=True)
    rows, prev = [], None
    for arm, label in (("trained", "Trained on levels"), ("posthoc", "Post-hoc")):
        for B in SELECTABLE:
            if prev is not None:
                rows.append("\\groupsep" if arm != prev else "\\rowsep")
            cells = []
            for st, ax in SLICES:
                h = d[(d.arm == arm) & (d.stream == st) & (d.axis == ax) & (d.B == B)].qwk
                h = h.dropna()
                if h.empty:
                    cells.append("& & & ")
                    continue
                cells.append(f"${h.mean():+.4f}$ & ${h.std(ddof=0):.4f}$ & "
                             f"$[{h.min():+.3f}, {h.max():+.3f}]$ & {len(h)}")
            rows.append(f"{label}, {B} & " + " & ".join(cells) + r" \\")
            prev = arm
    return "\n".join(rows)


def fold_rows(stream, axis):
    """Per-visitor agreement at every selectable count, the trained arm then the post-hoc."""
    frames = []
    for arm in ("trained", "posthoc"):
        f = OUT_DIR / f"sweep_{arm}_perfold.csv"
        if f.is_file():
            frames.append(pd.read_csv(f))
    d = pd.concat(frames, ignore_index=True)
    d = d[(d.stream == stream) & (d.axis == axis) & (d.B.isin(SELECTABLE))]
    if d.empty:
        return "", 0
    piv = d.pivot_table(index="participant", columns=["arm", "B"], values="qwk")
    cols = [(a, b) for a in ("trained", "posthoc") for b in SELECTABLE if (a, b) in piv.columns]
    piv = piv.reindex(columns=pd.MultiIndex.from_tuples(cols))
    lines = []
    for pid, r in piv.iterrows():
        vals = " & ".join("--" if pd.isna(v) else f"${v:+.2f}$" for v in r)
        lines.append(f"{pid} & {vals} \\\\")
    mean = " & ".join("--" if pd.isna(v) else f"${v:+.2f}$" for v in piv.mean(axis=0))
    # mean, spread and range, so every per-fold table closes the same way
    sd = " & ".join("--" if pd.isna(v) else f"${v:.2f}$" for v in piv.std(axis=0, ddof=0))
    rng = " & ".join("--" if pd.isna(piv[c].min())
                     else f"$[{piv[c].min():+.2f}, {piv[c].max():+.2f}]$" for c in piv.columns)
    body = "\n\\rowsep\n".join(lines)
    body += "\n\\groupsep\n" + f"Mean & {mean} \\\\"
    body += "\n\\rowsep\n" + f"SD & {sd} \\\\"
    body += "\n\\rowsep\n" + f"[Min, Max] & {rng} \\\\"
    return body, len(cols)


def main():
    head4 = spanhead(2, [f"{s} {a}" for s, a in SLICES])
    sub4 = " & ".join(["Tr. & Post."] * 4)

    parts = [r"""\chapter{Experiment 3 Tables}
\label{app:alt-experiment3}

Every level count Experiment~3 swept, on both arms and in every slice, with the occupancy
rule that decides which counts are selectable and the folds behind each figure. Tr. is the
trained-on-levels arm and Post. the post-hoc arm. A count marked $\dagger$ fails the
occupancy rule and is scored and reported but never carried.

\begin{table}[H]
\centering
\scriptsize
\caption{Experiment 3: pooled \ac{QWK} at every level count, on both arms and in every slice. Counts below the rule are separated from those above it; a count marked $\dagger$ holds a level occupied by less than one per cent of the rated seconds and is not selectable.}
\label{tab:alt-app-exp3-qwk}
\renewcommand{\arraystretch}{1.1}%
\setlength{\aboverulesep}{0pt}\setlength{\belowrulesep}{0pt}%
\begin{adjustbox}{max width=\linewidth, max totalheight=0.9\textheight}
\begin{tabular}{!{\tabedge}l!{\colsepline}rr!{\colsepline}rr!{\colsepline}rr!{\colsepline}rr!{\tabedge}}
\toprule
& """ + head4 + r""" \\
Levels & """ + sub4 + r""" \\
\midrule
""" + sweep_rows("qwk") + r"""
\bottomrule
\end{tabular}
\end{adjustbox}
\end{table}

\begin{table}[H]
\centering
\scriptsize
\caption{Experiment 3: balanced accuracy at every level count, on both arms and in every slice. Each value is read against its own chance level of $1/B$, which falls from $0.333$ at three levels to $0.050$ at twenty, so a column may not be compared down its own length. Balanced accuracy is a proportion in $[0, 1]$.}
\label{tab:alt-app-exp3-ba}
\renewcommand{\arraystretch}{1.1}%
\setlength{\aboverulesep}{0pt}\setlength{\belowrulesep}{0pt}%
\begin{adjustbox}{max width=\linewidth, max totalheight=0.9\textheight}
\begin{tabular}{!{\tabedge}l!{\colsepline}rr!{\colsepline}rr!{\colsepline}rr!{\colsepline}rr!{\tabedge}}
\toprule
& """ + head4 + r""" \\
Levels & """ + sub4 + r""" \\
\midrule
""" + sweep_rows("balanced_accuracy") + r"""
\bottomrule
\end{tabular}
\end{adjustbox}
\end{table}

\begin{table}[H]
\centering
\footnotesize
\caption{Experiment 3: the occupancy rule. Each slice's column gives the share of rated seconds falling in that count's emptiest level, as a percentage. A count is selectable only where every level holds at least one per cent in every slice. The parity column records whether the scale midpoint falls inside a level or on a boundary between two.}
\label{tab:alt-app-exp3-occupancy}
\renewcommand{\arraystretch}{1.2}%
\setlength{\aboverulesep}{0pt}\setlength{\belowrulesep}{0pt}%
\begin{adjustbox}{max width=\linewidth, max totalheight=0.9\textheight}
\begin{tabular}{!{\tabedge}l!{\colsepline}rrrr!{\colsepline}l!{\colsepline}l!{\tabedge}}
\toprule
& \multicolumn{4}{c!{\colsepline}}{Emptiest level (\% of rated seconds)} & & \\
Levels & rcea val & rcea aro & retro val & retro aro & Midpoint & Selectable \\
\midrule
""" + occupancy_rows() + r"""
\bottomrule
\end{tabular}
\end{adjustbox}
\end{table}

\begin{table}[H]
\centering
\footnotesize
\caption{Experiment 3: the selection in each slice, on the carried trained-on-levels arm. Every selectable count ties within the margin of $0.21$, so the coarsest is carried in all four slices. The jackknife repeats the comparison with each visitor held out in turn and reports how often the same count still comes first.}
\label{tab:alt-app-exp3-selection}
\renewcommand{\arraystretch}{1.2}%
\setlength{\aboverulesep}{0pt}\setlength{\belowrulesep}{0pt}%
\begin{adjustbox}{max width=\linewidth}
\begin{tabular}{!{\tabedge}l!{\colsepline}rrr!{\colsepline}ll!{\colsepline}rrr!{\tabedge}}
\toprule
Slice & Best & Its \ac{QWK} & Span & Tied & Carried & Jack. best & Stable & Share \\
\midrule
""" + selection_rows() + r"""
\bottomrule
\end{tabular}
\end{adjustbox}
\end{table}

\begin{table}[H]
\centering
\scriptsize
\caption{Experiment 3: per-visitor \ac{QWK} at every selectable count, on both arms, as mean, standard deviation, range, and number of visitors scored. The sweeps above report the pooled figure, computed once over every held-out prediction; this table gives the spread across visitors behind it. The two disagree in sign on three of the four slices, which is the pooling property Section~\ref{sec:results-exp3-pooling} reports. The visitor count falls below the fold count wherever a visitor's binned ratings and predictions both occupy a single level, for whom no kappa is defined.}
\label{tab:alt-app-exp3-summary}
\renewcommand{\arraystretch}{1.1}%
\setlength{\aboverulesep}{0pt}\setlength{\belowrulesep}{0pt}%
\begin{adjustbox}{max width=\linewidth, max totalheight=0.9\textheight}
\begin{tabular}{""" + bordered("l" + "rrrr" * len(SLICES)) + r"""}
\toprule
& \multicolumn{4}{c!{\colsepline}}{rcea valence} & \multicolumn{4}{c!{\colsepline}}{rcea arousal} & \multicolumn{4}{c!{\colsepline}}{retro valence} & \multicolumn{4}{c!{\tabedge}}{retro arousal} \\
Arm, levels & Mean & SD & [Min, Max] & $n$ & Mean & SD & [Min, Max] & $n$ & Mean & SD & [Min, Max] & $n$ & Mean & SD & [Min, Max] & $n$ \\
\midrule
""" + summary_rows() + r"""
\bottomrule
\end{tabular}
\end{adjustbox}
\end{table}
"""]

    for stream, axis in SLICES:
        body, ncol = fold_rows(stream, axis)
        if not body:
            continue
        head = " & ".join(str(b) for b in SELECTABLE)
        parts.append(r"""
\begin{table}[H]
\centering
\scriptsize
\caption{Experiment 3: per held-out visitor \ac{QWK} at every selectable level count, """
+ f"{stream} {axis}" + r""". The trained-on-levels arm first, then the post-hoc arm. A dash marks a visitor whose binned ratings and predictions both occupy a single level, for whom no kappa is defined. The last three rows give the mean, the population standard deviation, and the range across the visitors above them.}
\label{tab:alt-app-exp3-folds-""" + f"{stream}-{axis}" + r"""}
\renewcommand{\arraystretch}{1.1}%
\setlength{\aboverulesep}{0pt}\setlength{\belowrulesep}{0pt}%
\begin{adjustbox}{max width=\linewidth, max totalheight=0.9\textheight}
\begin{tabular}{!{\tabedge}l!{\colsepline}""" + "r" * (ncol // 2) + r"""!{\colsepline}""" + "r" * (ncol - ncol // 2) + r"""!{\tabedge}}
\toprule
& \multicolumn{""" + str(ncol // 2) + r"""}{c!{\colsepline}}{Trained on levels} & \multicolumn{""" + str(ncol - ncol // 2) + r"""}{c!{\tabedge}}{Post-hoc} \\
Visitor & """ + head + " & " + head + r""" \\
\midrule
""" + body + r"""
\bottomrule
\end{tabular}
\end{adjustbox}
\end{table}
""")

    open(TEX, "w").write(re.sub(r"\n{3,}", "\n\n", "\n".join(parts)).rstrip() + "\n")
    print(f"written to {TEX}")


if __name__ == "__main__":
    main()

scripts/exp1_v2/make_exp4_appendix.py.text:
"""Write Experiment 4's appendix from the stored scores.

Four kinds of table. The scoping comparison, summarised on all three metrics and then given
per held-out visitor. The paired tests behind every claim of a difference. The same
comparison painting by painting, with cells that fail the reporting thresholds marked rather
than dropped. Then the variance decomposition: the ratings' three shares with the checks
around them, the same split on the binned target and on the visitor-painting means, the
sensor rollup, and every feature's own split.

    python3 -u -m scripts.exp1_v2.make_exp4_appendix
"""
import re

import numpy as np
import pandas as pd

def spanhead(n, labels):
    """Spanning header cells: a rule to the right of each, the outer edge after the last."""
    cells = [f"\\multicolumn{{{n}}}{{c!{{\\colsepline}}}}{{{lab}}}" for lab in labels]
    cells[-1] = cells[-1].replace("!{\\colsepline}", "!{\\tabedge}")
    return " & ".join(cells)


def bordered(spec):
    """House column spec: outer \\tabedge rules and a \\colsepline between every column."""
    cols = [c for c in spec if c in "lcr"]
    return "!{\\tabedge}" + "!{\\colsepline}".join(cols) + "!{\\tabedge}"

from scripts.exp1_v2.selection import OUT

OUT_DIR = OUT / "exp4"
TEX = "/Users/akshaj/Documents/Thesis/research-proposal/appendix_final_exp4.tex"

SLICES = [("rcea", "valence"), ("rcea", "arousal"),
          ("retro", "valence"), ("retro", "arousal")]
PAINTINGS = ("B1", "B2", "B3", "C5", "C6")
QUANTS = [("whole_session", "Whole session"),
          ("whole_on_attended", "Whole, scored on attended"),
          ("attended_trained", "Attended-trained")]
CATEGORY = {"pupil": "Pupil and gaze", "eda": "Electrodermal", "hrv": "Cardiac",
            "speech_acoustics": "Speech acoustics", "speech_content": "Speech content",
            "cross_sensor": "Cross-sensor block"}


def esc(s):
    return str(s).replace("_", "\\_")


def scoping_summary():
    """One block per statistic, four slice columns each, so the table reads down rather than across."""
    c = pd.read_csv(OUT_DIR / "scoping.csv")
    f = pd.read_csv(OUT_DIR / "scoping_perfold.csv")
    SPAN = "\\multicolumn{5}{!{\\tabedge}l!{\\tabedge}}{%s} \\\\"
    stats = [('mean', 'Mean per-visitor \\ac{CCC}', '${g.mean():+.4f}$'), ('sd', 'Population standard deviation of per-visitor \\ac{CCC}', '${g.std(ddof=0):.4f}$'), ('range', 'Range of per-visitor \\ac{CCC}, [min, max]', '$[{g.min():+.3f}, {g.max():+.3f}]$'), ('qwk', 'Pooled \\ac{QWK}', '${r.qwk_pooled:+.4f}$'), ('ba', 'Balanced accuracy, against a chance value of $0.333$', '${r.balanced_accuracy:.3f}$')]
    out = []
    for b, (_, title, fmt) in enumerate(stats):
        if b:
            out.append("\\groupsep")
        out.append(SPAN % title)
        out.append("\\rowsep")
        prev = None
        for k, (key, label) in enumerate(QUANTS):
            grp = None
            if k:
                out.append("\\groupsep" if grp != prev else "\\rowsep")
            cells = []
            for st, ax in SLICES:
                h = c[(c.stream == st) & (c.axis == ax) & (c.quantity == key)]
                g = f[(f.stream == st) & (f.axis == ax) & (f.quantity == key)].ccc
                if h.empty or g.empty:
                    cells.append("--")
                    continue
                r = h.iloc[0]
                cells.append(eval(f"f{fmt!r}"))
            out.append(f"{label} & " + " & ".join(cells) + " \\\\")
            prev = grp
    return "\n".join(out)


def counts_rows():
    c = pd.read_csv(OUT_DIR / "scoping.csv")
    rows = []
    for key, label in QUANTS:
        cells = []
        for st, ax in SLICES:
            h = c[(c.stream == st) & (c.axis == ax) & (c.quantity == key)]
            cells.append(f"{int(h.rows.iloc[0]):,} & {int(h.participants.iloc[0])}"
                         if len(h) else "& ")
        rows.append(f"{label} & " + " & ".join(cells) + r" \\")
    return "\n\\rowsep\n".join(rows)


def tests_rows(scope):
    t = pd.read_csv(OUT_DIR / "tests.csv")
    t = t[t.painting == "all"] if scope == "pooled" else t[t.painting != "all"]
    if t.empty:
        return ""
    rows = []
    for comp, g1 in t.groupby("comparison"):
        for metric, g2 in g1.groupby("metric"):
            for r in g2.sort_values(["painting", "stream", "axis"]).itertuples():
                star = "$^{*}$" if r.significant else ""
                rows.append(
                    f"{esc(r.comparison)} & {metric.upper()} & {r.painting} & "
                    f"{r.stream} {r.axis} & {int(r.n)} & ${r.mean_a:+.4f}$ & "
                    f"${r.mean_b:+.4f}$ & ${r.delta:+.4f}$ & {int(r.improved)} & "
                    f"${r.p:.3f}$ & ${r.q:.3f}${star}" + r" \\")
    return "\n\\rowsep\n".join(rows)


def perpainting_rows(metric):
    c = pd.read_csv(OUT_DIR / "perpainting.csv")
    rows, prev = [], None
    for p in PAINTINGS:
        for key, label in QUANTS:
            if prev is not None:
                rows.append("\\groupsep" if p != prev else "\\rowsep")
            cells = []
            for st, ax in SLICES:
                h = c[(c.painting == p) & (c.stream == st) & (c.axis == ax)
                      & (c.quantity == key)]
                if h.empty or not bool(h.reportable.iloc[0]):
                    cells.append("n.r.")
                    continue
                v = h[metric].iloc[0]
                cells.append("n.r." if pd.isna(v) else f"${v:+.4f}$")
            rows.append(f"{p} & {label} & " + " & ".join(cells) + r" \\")
            prev = p
    return "\n".join(rows)


def variance_rows():
    r = pd.read_csv(OUT_DIR / "variance_ratings.csv")
    rows = []
    for st, ax in SLICES:
        h = r[(r.stream == st) & (r.axis == ax)]
        if h.empty:
            continue
        v = h.iloc[0]
        rows.append(
            f"{st} {ax} & {int(v.n_rows):,} & {int(v.n_participants)} & "
            f"${v.me_between_person_pct:.1f}$ & ${v.me_between_painting_pct:.1f}$ & "
            f"${v.me_residual_pct:.1f}$ & "
            f"$[{v.me_painting_ci_lo:.1f}, {v.me_painting_ci_hi:.1f}]$ & "
            f"$[{v.me_painting_jack_min:.1f}, {v.me_painting_jack_max:.1f}]$ & "
            f"${v.eta2_painting_pct:.2f}$ & ${v.eta2_person_pct:.2f}$" + r" \\")
    return "\n\\rowsep\n".join(rows)


def variance_alt_rows():
    """The same split on the binned target and on the visitor-painting means."""
    b = pd.read_csv(OUT_DIR / "variance_binned.csv")
    i = pd.read_csv(OUT_DIR / "variance_icc.csv")
    rows = []
    for st, ax in SLICES:
        hb = b[(b.stream == st) & (b.axis == ax)]
        hi = i[(i.stream == st) & (i.axis == ax)]
        if hb.empty or hi.empty:
            continue
        vb, vi = hb.iloc[0], hi.iloc[0]
        rows.append(
            f"{st} {ax} & ${vb.me_between_person_pct:.1f}$ & "
            f"${vb.me_between_painting_pct:.1f}$ & ${vb.me_residual_pct:.1f}$ & "
            f"{int(vi.n_cells)} & ${vi.me_between_person_pct:.1f}$ & "
            f"${vi.me_between_painting_pct:.1f}$ & ${vi.me_residual_pct:.1f}$ & "
            f"${vi.icc_painting_as_target:.4f}$" + r" \\")
    return "\n\\rowsep\n".join(rows)


def sensors_rows():
    s = pd.read_csv(OUT_DIR / "variance_sensors.csv")
    rows, prev = [], None
    for stream in ("rcea", "retro"):
        for cat in ("pupil", "eda", "hrv", "speech_acoustics", "speech_content",
                    "cross_sensor"):
            h = s[(s.stream == stream) & (s.category == cat)]
            if h.empty:
                continue
            if prev is not None:
                rows.append("\\groupsep" if stream != prev else "\\rowsep")
            v = h.iloc[0]
            rows.append(
                f"{stream} & {CATEGORY[cat]} & ${v.person_pct:.2f}$ & "
                f"${v.painting_pct:.2f}$ & ${v.residual_pct:.2f}$ & "
                f"${v.eta2_painting_pct:.2f}$ & {int(v.n_features)} & "
                f"{int(v.n_degenerate)} & {int(v.n_total)}" + r" \\")
            prev = stream
    return "\n".join(rows)


KEPT_ACOUSTIC = {  # the five eGeMAPS means the literature commits a direction on; the other 83 are omitted for legibility
    "speech_egemaps_f0semitonefrom27_5hz_sma3nz_amean": "F0 mean (semitones)",
    "speech_egemaps_loudness_sma3_amean": "loudness mean",
    "speech_egemaps_jitterlocal_sma3nz_amean": "jitter, local",
    "speech_egemaps_shimmerlocaldb_sma3nz_amean": "shimmer, local (dB)",
    "speech_egemaps_hnrdbacf_sma3nz_amean": "HNR (dB)",
}


def features_rows():
    f = pd.read_csv(OUT_DIR / "variance_features.csv")
    keep = (f.category != "speech_acoustics") | f.feature.isin(KEPT_ACOUSTIC)
    f = f[keep]
    lines = []
    for stream in ("rcea", "retro"):
        g = f[f.stream == stream].sort_values(["category", "feature"])
        for r in g.itertuples():
            if r.reml_degenerate:
                cells = "\\multicolumn{3}{c!{\\colsepline}}{degenerate}"
            else:
                cells = (f"${r.person_reml_pct:.2f}$ & ${r.painting_reml_pct:.2f}$ & "
                         f"${r.residual_reml_pct:.2f}$")
            # the Category column already names the sensor, so the feature's own prefix is dropped
            name = KEPT_ACOUSTIC.get(r.feature, esc(r.feature.split("__", 1)[-1]))
            lines.append(f"{stream} & {name} & {CATEGORY.get(r.category, r.category)}"
                         f" & {cells} & ${r.eta2_painting_pct:.2f}$ \\\\")
    return "\n\\rowsep\n".join(lines)


def fold_rows(stream, axis):
    f = pd.read_csv(OUT_DIR / "scoping_perfold.csv")
    g = f[(f.stream == stream) & (f.axis == axis)]
    if g.empty:
        return "", 0
    piv = g.pivot_table(index="participant", columns="quantity", values=["ccc", "qwk"])
    cols = [(m, k) for m in ("ccc", "qwk") for k, _ in QUANTS if (m, k) in piv.columns]
    piv = piv.reindex(columns=pd.MultiIndex.from_tuples(cols))
    lines = []
    for pid, r in piv.iterrows():
        vals = " & ".join("--" if pd.isna(v) else f"${v:+.2f}$" for v in r)
        lines.append(f"{pid} & {vals} \\\\")
    body = "\n\\rowsep\n".join(lines)
    mean = " & ".join("--" if pd.isna(v) else f"${v:+.2f}$" for v in piv.mean(axis=0))
    # mean, spread and range, so every per-fold table closes the same way
    sd = " & ".join("--" if pd.isna(v) else f"${v:.2f}$" for v in piv.std(axis=0, ddof=0))
    rng = " & ".join("--" if pd.isna(piv[c].min())
                     else f"$[{piv[c].min():+.2f}, {piv[c].max():+.2f}]$" for c in piv.columns)
    return (body + "\n\\groupsep\n" + f"Mean & {mean} \\\\"
            + "\n\\rowsep\n" + f"SD & {sd} \\\\"
            + "\n\\rowsep\n" + f"[Min, Max] & {rng} \\\\"), len(cols)


