scripts/exp1_v2/verify_results.py.text:
"""Check the thesis's results tables against the files they came from.

Every table in the results chapter is typed by hand, which is exactly where a wrong number
survives review: the prose reads plausibly and nothing crashes. Each check below re-derives
one table from the stored scores and reports any cell that disagrees.

The previous generation's checker pointed at result paths and table labels that no longer
exist, so it verified nothing while reporting success as a skip. This one fails loudly when a
file or a label is missing, because a checker that cannot find its data is a broken checker
and not a passing one.

    python3 -u -m scripts.exp1_v2.verify_results

Exit status is non-zero when any cell disagrees, or when any check could not run.
"""
import re
import sys

import numpy as np
import pandas as pd

from scripts.exp1_v2.selection import OUT

BODY = "/Users/akshaj/Documents/Thesis/research-proposal/final_thesis_body.tex"
TOL = 5e-5                         # tables are quoted to four decimals
SLICES = [("rcea", "valence"), ("rcea", "arousal"),
          ("retro", "valence"), ("retro", "arousal")]


class Report:
    def __init__(self):
        self.checked = 0
        self.bad = []
        self.broken = []

    def cell(self, name, claimed, actual, tol=TOL):
        self.checked += 1
        if claimed is None or actual is None or not np.isfinite(actual):
            self.bad.append(f"{name}: no value (thesis {claimed}, data {actual})")
        elif abs(claimed - actual) > tol:
            self.bad.append(f"{name}: thesis {claimed:+.4f}, data {actual:+.4f}")

    def broke(self, name, why):
        self.broken.append(f"{name}: {why}")

    def done(self):
        print(f"\nchecked {self.checked} table cells")
        for b in self.bad:
            print(f"  MISMATCH  {b}")
        for b in self.broken:
            print(f"  COULD NOT RUN  {b}")
        if self.checked == 0:
            print("VERIFIED NOTHING")
            return 1
        if self.bad or self.broken:
            print(f"\n{len(self.bad)} mismatches, {len(self.broken)} checks could not run")
            return 1
        print("all cells agree")
        return 0


def table_rows(label):
    """The data rows of the table carrying this label, as raw LaTeX lines.

    Anchored on the label and walked outward to the enclosing table, rather than matched from
    the first \\begin{table} in the file: a lazy match from the start spans several tables and
    silently returns the wrong one.
    """
    text = open(BODY).read()
    at = text.find("\\label{" + label + "}")
    if at < 0:
        return None
    start = text.rfind("\\begin{table}", 0, at)
    end = text.find("\\end{table}", at)
    if start < 0 or end < 0:
        return None
    block = text[start:end]
    # a table may hold several panels side by side; gather the rows of every one
    rows = []
    for m in re.finditer(r"\\midrule(.*?)(?=\\bottomrule|$)", block, re.S):
        rows += [ln.strip() for ln in m.group(1).splitlines()
                 if "&" in ln or "\\multicolumn" in ln]
    return rows or None


def nums(line):
    """Every signed decimal in one table row, in order."""
    return [float(x.replace("+", "")) for x in
            re.findall(r"[-+]?\d+\.\d+", line.replace("\\", " "))]


def block_field(line):
    """The metric a stacked block header names, or None for a data row."""
    if "\\multicolumn" not in line:
        return None
    if "CCC" in line:
        return "ccc_mean"
    if "QWK" in line:
        return "qwk_pooled"
    if "Balanced" in line:
        return "balanced_accuracy"
    return None


def read(rel):
    p = OUT / rel
    return pd.read_csv(p) if p.is_file() else None


# ---------------------------------------------------------------- the checks

def check_alignment(rep):
    label = "tab:alt-alignment-arms"
    rows, d = table_rows(label), read("exp2/alignment.csv")
    if rows is None or d is None:
        return rep.broke(label, "table or exp2/alignment.csv missing")
    names = {"Fixed windowing": "fixed", "\\ac{DTW}": "dtw",
             "\\ac{DCCA}": "dcca", "\\ac{DCTW}": "dctw"}
    for ln in rows:
        head = ln.split("&")[0].strip()
        if head not in names:
            continue
        arm, v = names[head], nums(ln)
        if len(v) < 5:
            continue
        for (st, ax), claimed in zip(SLICES, v[:4]):
            h = d[(d.stream == st) & (d.axis == ax) & (d.arm == arm)]
            rep.cell(f"{label} {arm} {st}/{ax}", claimed,
                     float(h.ccc_mean.iloc[0]) if len(h) else None)
        rep.cell(f"{label} {arm} mean", v[4],
                 float(d[d.arm == arm].ccc_mean.mean()))


def check_crosssensor(rep):
    label = "tab:alt-crosssensor"
    rows, d = table_rows(label), read("exp2/crosssensor.csv")
    if rows is None or d is None:
        return rep.broke(label, "table or exp2/crosssensor.csv missing")
    window = None
    for ln in rows:
        first = ln.split("&")[0].strip()
        m = re.match(r"(\d+)\\,s", first)
        if m:
            window = int(m.group(1))
        if window is None:
            continue
        kind = "observed" if "observed" in ln else ("p95" if "surrogate" in ln else None)
        if kind is None:
            continue
        # the window label is "5\,s", which carries no decimal, so nums() never sees it
        v = nums(ln)
        for (st, ax), claimed in zip(SLICES, v[:4]):
            g = d[(d.stream == st) & (d.axis == ax) & (d.window_s == window)]
            if g.empty:
                rep.cell(f"{label} {window}s {kind} {st}/{ax}", claimed, None)
                continue
            actual = (float(g[g.arm == "observed"].ccc_mean.iloc[0]) if kind == "observed"
                      else float(g[g.arm != "observed"].ccc_mean.quantile(0.95)))
            rep.cell(f"{label} {window}s {kind} {st}/{ax}", claimed, actual)


def check_exp3_arms(rep):
    # The balanced-accuracy table carries a chance column before the eight scores, and quotes
    # three decimals rather than four, so it is parsed and compared on its own terms.
    for label, col, skip, tol in (("tab:alt-exp3-arms", "qwk", 0, TOL),
                                  ("tab:alt-exp3-ba", "balanced_accuracy", 1, 5e-4)):
        rows = table_rows(label)
        tr, po = read("exp3/sweep_trained.csv"), read("exp3/sweep_posthoc.csv")
        if rows is None or tr is None or po is None:
            rep.broke(label, "table or exp3 sweeps missing")
            continue
        for ln in rows:
            head = ln.split("&")[0].strip()
            if not head.isdigit():
                continue
            B, v = int(head), nums(ln)[skip:]
            if len(v) < 8:
                continue
            for arm, d, off in (("trained", tr, 0), ("posthoc", po, 4)):
                for (st, ax), claimed in zip(SLICES, v[off:off + 4]):
                    h = d[(d.stream == st) & (d.axis == ax) & (d.B == B)]
                    rep.cell(f"{label} B={B} {arm} {st}/{ax}", claimed,
                             float(h[col].iloc[0]) if len(h) else None, tol=tol)


def check_exp1_summary(rep):
    """Per-sensor mean and spread under the standard model, per slice."""
    label = "tab:alt-experiment1-summary"
    rows = table_rows(label)
    if rows is None:
        return rep.broke(label, "table missing")
    import glob
    files = glob.glob(str(OUT / "families" / "cell_*.csv"))
    if not files:
        return rep.broke(label, "families/cell_*.csv missing")
    d = pd.concat([pd.read_csv(f) for f in files])
    d = d[d.family == "extra_trees"]
    names = {"Pupil and gaze": "pupil", "\\ac{EDA}": "eda", "\\ac{HRV}": "hrv",
             "Speech acoustics": "speech_acoustics", "Speech content": "speech_content"}
    for ln in rows:
        head = ln.split("&")[0].strip()
        if head not in names:
            continue
        sensor, v = names[head], nums(ln)
        if len(v) < 8:
            continue
        for i, (st, ax) in enumerate(SLICES):
            g = d[(d.stream == st) & (d.axis == ax) & (d.sensor == sensor)]
            rep.cell(f"{label} {sensor} {st}/{ax} mean", v[2 * i],
                     float(g.ccc.mean()) if len(g) else None)


def check_fusion_sizes(rep):
    """Every subset under every mechanism, as the body table reports them."""
    label = "tab:alt-fusion-sizes"
    rows = table_rows(label)
    fu, ba = read("exp2/fusion.csv"), read("exp2/fusion_block_arms_all.csv")
    if rows is None or fu is None or ba is None:
        return rep.broke(label, "table or exp2 fusion files missing")
    mech = ["early", "late_ccc", "late_simple"]
    for ln in rows:
        head = ln.split("&")[0].strip()
        if not re.fullmatch(r"[PEHS][a-c]?(\+[PEHS][a-c]?)*", head):
            continue
        v = nums(ln)
        cells = [c.strip() for c in ln.split("&")[1:]]
        got = 0
        for j, m in enumerate(mech):
            if j < len(cells) and cells[j].startswith("--"):
                continue
            h = fu[(fu.subset == head) & (fu.mechanism == m)]
            if got < len(v):
                rep.cell(f"{label} {head} {m}", v[got],
                         float(h.ccc_mean.mean()) if len(h) else None)
                got += 1
        h = ba[ba.subset == head]
        if got < len(v):
            rep.cell(f"{label} {head} early+block", v[got],
                     float(h.ccc_mean.mean()) if len(h) else None)


def check_exp4_body_tables(rep):
    """The two Experiment 4 tables in the results chapter, cell by cell."""
    label = "tab:alt-exp4-scoping"
    rows, d = table_rows(label), read("exp4/scoping.csv")
    if rows is None or d is None:
        rep.broke(label, "table or exp4/scoping.csv missing")
    else:
        names = {"Whole session": "whole_session",
                 "Whole, on attended rows": "whole_on_attended",
                 "Attended-trained": "attended_trained"}
        tols = {"ccc_mean": TOL, "qwk_pooled": TOL, "balanced_accuracy": 5e-4}
        field = None
        for ln in rows:
            f = block_field(ln)
            if f:
                field = f
                continue
            head = ln.split("&")[0].strip()
            if head not in names or field is None:
                continue
            q, v = names[head], nums(ln)
            if len(v) < 4:
                continue
            for k, (st, ax) in enumerate(SLICES):
                h = d[(d.stream == st) & (d.axis == ax) & (d.quantity == q)]
                rep.cell(f"{label} {q} {field} {st}/{ax}", v[k],
                         float(h[field].iloc[0]) if len(h) else None, tol=tols[field])

    label = "tab:alt-exp4-variance"
    rows = table_rows(label)
    v_, b_, i_ = (read("exp4/variance_ratings.csv"), read("exp4/variance_binned.csv"),
                  read("exp4/variance_icc.csv"))
    if rows is None or v_ is None or b_ is None or i_ is None:
        return rep.broke(label, "table or exp4 variance files missing")
    for ln in rows:
        head = ln.split("&")[0].strip()
        parts = head.split()
        if len(parts) != 2 or parts[0] not in ("rcea", "retro"):
            continue
        st, ax = parts
        n = nums(ln)
        if len(n) < 10:
            continue
        r = v_[(v_.stream == st) & (v_.axis == ax)]
        rb = b_[(b_.stream == st) & (b_.axis == ax)]
        ri = i_[(i_.stream == st) & (i_.axis == ax)]
        if r.empty or rb.empty or ri.empty:
            rep.broke(f"{label} {st}/{ax}", "row missing from results")
            continue
        r, rb, ri = r.iloc[0], rb.iloc[0], ri.iloc[0]
        for k, (name, actual, tol) in enumerate([
                ("person", r.me_between_person_pct, 0.05),
                ("painting", r.me_between_painting_pct, 0.05),
                ("residual", r.me_residual_pct, 0.05),
                ("ci lo", r.me_painting_ci_lo, 0.05),
                ("ci hi", r.me_painting_ci_hi, 0.05),
                ("jack min", r.me_painting_jack_min, 0.05),
                ("jack max", r.me_painting_jack_max, 0.05),
                ("eta2", r.eta2_painting_pct, 5e-3),
                ("binned painting", rb.me_between_painting_pct, 0.05),
                ("icc", ri.icc_painting_as_target, 5e-4)]):
            rep.cell(f"{label} {st}/{ax} {name}", n[k], float(actual), tol=tol)


def check_exp5_body_table(rep):
    """The Experiment 5 lever table in the results chapter, cell by cell. The table is stacked,
    one block per metric, so the metric comes from the block header above each row."""
    label = "tab:alt-exp5-levers"
    rows, d = table_rows(label), read("exp5/levers.csv")
    if rows is None or d is None:
        return rep.broke(label, "table or exp5/levers.csv missing")
    names = {"No personalisation": "reference",
             "Baseline-window calibration": "baseline",
             "Labelled warm-up, 30\\,s": "warmup_30",
             "Labelled warm-up, 60\\,s": "warmup_60",
             "Labelled warm-up, 120\\,s": "warmup_120",
             "Labelled warm-up, 180\\,s": "warmup_180",
             "Person-relative target": "person_relative"}
    tols = {"ccc_mean": TOL, "qwk_pooled": TOL, "balanced_accuracy": 5e-4}
    field = None
    for ln in rows:
        f = block_field(ln)
        if f:
            field = f
            continue
        head = ln.split("&")[0].strip()
        if head not in names or field is None:
            continue
        arm, v = names[head], nums(ln)
        # nums() reads decimals only, so the "30\\,s" in a warm-up label is never picked up
        if len(v) < 4:
            continue
        for k, (st, ax) in enumerate(SLICES):
            h = d[(d.stream == st) & (d.axis == ax) & (d.arm == arm)]
            rep.cell(f"{label} {arm} {field} {st}/{ax}", v[k],
                     float(h[field].iloc[0]) if len(h) else None, tol=tols[field])

def check_exp4_scoping(rep):
    """The scoping figures quoted in the results prose, against the stored cells."""
    d = read("exp4/scoping.csv")
    if d is None:
        return rep.broke("exp4 scoping", "exp4/scoping.csv missing")
    text = open(BODY).read()
    for st, ax, q, field in (("rcea", "valence", "whole_session", "ccc_mean"),
                             ("rcea", "arousal", "whole_session", "ccc_mean"),
                             ("retro", "valence", "whole_session", "ccc_mean"),
                             ("retro", "arousal", "whole_session", "ccc_mean")):
        h = d[(d.stream == st) & (d.axis == ax) & (d.quantity == q)]
        if h.empty:
            rep.broke(f"exp4 {st}/{ax}", "cell missing")
            continue
        val = float(h[field].iloc[0])
        rep.checked += 1
        if f"{val:+.4f}" not in text:
            rep.bad.append(f"exp4 {st}/{ax} {q}: {val:+.4f} appears nowhere in the body")


def check_exp5_levers(rep):
    """The claims the results chapter makes about the levers, rather than arbitrary cells:
    how many cells moved up on each metric, that the person-relative target leaves the
    continuous score untouched, and the largest movement the warm-up produced."""
    d = read("exp5/levers.csv")
    t = read("exp5/tests.csv")
    if d is None or t is None:
        return rep.broke("exp5 levers", "exp5/levers.csv or tests.csv missing")
    text = open(BODY).read()
    ref = d[d.arm == "reference"].set_index(["stream", "axis"])
    rows = []
    for r in d[d.arm != "reference"].itertuples():
        b = ref.loc[(r.stream, r.axis)]
        rows.append((r.arm, r.ccc_mean - b.ccc_mean, r.qwk_pooled - b.qwk_pooled,
                     r.balanced_accuracy - b.balanced_accuracy))
    D = pd.DataFrame(rows, columns=["arm", "dccc", "dqwk", "dba"])

    for name, n in (("pooled QWK", int((D.dqwk > 0).sum())),
                    ("balanced accuracy", int((D.dba > 0).sum())),
                    ("CCC", int((D.dccc > 0).sum()))):
        rep.checked += 1
        if f"{n}" not in text:
            rep.bad.append(f"exp5 cells up on {name}: {n} of {len(D)} appears nowhere")

    # the person-relative target leaves the regressor untouched, so its continuous score
    # must equal its reference's exactly; a non-zero here is a bug in the lever, not the prose
    rep.checked += 1
    pr = D[D.arm == "person_relative"].dccc
    if not np.allclose(pr, 0.0, atol=1e-9):
        rep.bad.append(f"person-relative CCC is not identical to its reference: {list(pr)}")

    rep.checked += 1
    big = D[D.arm.str.startswith("warmup")].dqwk.max()
    if f"{big:+.4f}" not in text:
        rep.bad.append(f"largest warm-up QWK movement {big:+.4f} appears nowhere")

    rep.checked += 1
    q = float(t.q.min())
    if f"{q:.3f}" not in text:
        rep.bad.append(f"smallest adjusted p {q:.3f} appears nowhere")
    rep.checked += 1
    if int(t.significant.sum()) != 0:
        rep.bad.append(f"{int(t.significant.sum())} tests survive correction; "
                       "the chapter says none does")


def check_variance(rep):
    """The three shares quoted in the results and discussion."""
    d = read("exp4/variance_ratings.csv")
    if d is None:
        return rep.broke("exp4 variance", "exp4/variance_ratings.csv missing")
    text = open(BODY).read()
    lo, hi = d.me_between_painting_pct.min(), d.me_between_painting_pct.max()
    plo, phi = d.me_between_person_pct.min(), d.me_between_person_pct.max()
    for name, v in (("painting share low", lo), ("painting share high", hi),
                    ("person share low", plo), ("person share high", phi)):
        rep.checked += 1
        if f"${v:.1f}\\%$" not in text:
            rep.bad.append(f"variance {name}: ${v:.1f}\\%$ appears nowhere in the body")
    rep.checked += 1
    tot = d[["me_between_person_pct", "me_between_painting_pct",
             "me_residual_pct"]].sum(axis=1)
    if not np.allclose(tot, 100.0, atol=0.15):
        rep.bad.append(f"variance shares do not sum to 100: {list(tot.round(2))}")


def main():
    rep = Report()
    for fn in (check_exp1_summary, check_alignment, check_crosssensor, check_fusion_sizes,
               check_exp3_arms, check_exp4_body_tables, check_exp5_body_table,
               check_exp4_scoping, check_exp5_levers, check_variance):
        fn(rep)
    sys.exit(rep.done())


if __name__ == "__main__":
    main()

