"""
scripts/modeling/ccc_metrics.py
=================================
Concordance Correlation Coefficient (Lin, 1989) and a supporting regression
metric basket, for the Phase B.1-6 CCC-regression test (see plan.md).

Ported from ~/Documents/Thesisclean/utils/metrics.py (sibling repo, CCC-first
prior work) -- CCC formula and NaN-handling kept identical; the classification
(balanced-accuracy/region-label) half of that module is not needed here and
left out, since this project's classification path already lives in
scripts/modeling/evaluation.py.

Verified against a hand-computable toy example -- see
scripts/ccc_feature_engineering/verify_ccc_metric.py.
"""

import numpy as np
from scipy.stats import spearmanr


def concordance_correlation_coefficient(y_true, y_pred) -> float:
    """CCC = 2*cov / (var_t + var_p + (mean_t - mean_p)^2). Range [-1, 1]; 1 = perfect."""
    yt = np.asarray(y_true, dtype=float).ravel()
    yp = np.asarray(y_pred, dtype=float).ravel()
    m = np.isfinite(yt) & np.isfinite(yp)
    if int(m.sum()) < 2:
        return float("nan")
    yt, yp = yt[m], yp[m]
    mt, mp = yt.mean(), yp.mean()
    vt, vp = yt.var(), yp.var()
    cov = float(np.mean((yt - mt) * (yp - mp)))
    denom = vt + vp + (mt - mp) ** 2
    return float(2.0 * cov / denom) if denom > 0 else float("nan")


def _finite_pair(y_true, y_pred):
    yt = np.asarray(y_true, dtype=float).ravel()
    yp = np.asarray(y_pred, dtype=float).ravel()
    m = np.isfinite(yt) & np.isfinite(yp)
    if int(m.sum()) < 2:
        return np.empty(0), np.empty(0)
    return yt[m], yp[m]


def pearson_r(y_true, y_pred) -> float:
    yt, yp = _finite_pair(y_true, y_pred)
    if yt.size < 2 or yt.std() < 1e-8 or yp.std() < 1e-8:
        return float("nan")
    return float(np.corrcoef(yt, yp)[0, 1])


def spearman_rho(y_true, y_pred) -> float:
    yt, yp = _finite_pair(y_true, y_pred)
    if yt.size < 2 or yt.std() < 1e-8 or yp.std() < 1e-8:
        return float("nan")
    rho = spearmanr(yt, yp).correlation
    return float(rho) if rho is not None else float("nan")


def rmse(y_true, y_pred) -> float:
    yt, yp = _finite_pair(y_true, y_pred)
    if yt.size < 1:
        return float("nan")
    return float(np.sqrt(np.mean((yt - yp) ** 2)))


def mae(y_true, y_pred) -> float:
    yt, yp = _finite_pair(y_true, y_pred)
    if yt.size < 1:
        return float("nan")
    return float(np.mean(np.abs(yt - yp)))


def r2_score(y_true, y_pred) -> float:
    yt, yp = _finite_pair(y_true, y_pred)
    if yt.size < 2:
        return float("nan")
    ss_res = float(np.sum((yt - yp) ** 2))
    ss_tot = float(np.sum((yt - yt.mean()) ** 2))
    if ss_tot < 1e-12:
        return float("nan")
    return 1.0 - ss_res / ss_tot


def regression_metrics(y_true, y_pred) -> dict:
    """Full basket for one axis. CCC = agreement (location+scale+shape),
    Pearson = linear shape only, Spearman = monotonic rank, RMSE/MAE = error
    magnitude, R2 = variance explained. Reported together because CCC alone
    can look bad for reasons RMSE/R2 clarify (e.g. a shifted-but-correlated
    prediction), and vice versa (see plan.md's CCC-vs-RMSE citation, Kachele
    et al. 2016)."""
    return {
        "CCC": concordance_correlation_coefficient(y_true, y_pred),
        "Pearson": pearson_r(y_true, y_pred),
        "Spearman": spearman_rho(y_true, y_pred),
        "RMSE": rmse(y_true, y_pred),
        "MAE": mae(y_true, y_pred),
        "R2": r2_score(y_true, y_pred),
    }

scripts/thesis_v2/raw_coverage.py.text:
"""Per-second RAW-signal coverage, before any cleaning or feature extraction.

characterize.py measures coverage on the extracted feature parquets, so a low
figure there mixes two causes: the raw sensor genuinely not recording, and the
preprocessing chain rejecting what it did record. This script separates them by
asking only one question per second of the annotation window: did the raw sensor
produce at least one sample in that second?

Definitions (deliberately minimal, so the number means only what it says):
  * The window is the ANALYSED 1 Hz grid: the annotation loaders' own index,
    restricted to the seconds that survive build_features.py's pre-session trim
    (rcea's joystick starts ~6-7 min before any sensor, during a practice phase).
    Without that restriction the denominator would include seconds no sensor was
    ever recording in, and raw coverage would read lower than feature coverage
    for the same participant, which is how this was caught.
  * A second is covered if >=1 raw sample falls inside it. Pupil additionally
    reports a validity-gated variant using the tracker's own valid_left/right
    flags, since that flag is part of the raw record rather than our cleaning.
  * Speech is push-to-talk and its parquet is silence-removed, so its coverage
    is genuinely sparse by design and is reported, never flagged.

Usage:
  python3 -m scripts.thesis_v2.raw_coverage [--pids M01 M02]
Writes results/thesis_v2/characterization/raw_coverage_{summary,full}.csv
"""

from __future__ import annotations

import argparse
import pathlib
import warnings

import pandas as pd

warnings.filterwarnings("ignore")

from scripts.annotation.rcea_alignment import load_rcea_aligned
from scripts.annotation.retro_alignment import load_retro_aligned
from scripts.preprocessing.eda_processing import load_eda
from scripts.preprocessing.hrv_processing import load_bvp
from scripts.preprocessing.pupil_processing import load_pupil
from scripts.preprocessing.speech_processing import load_speech_audio
from scripts.utils import RCEA_PARTICIPANTS, RESULTS_ROOT, RETRO_PARTICIPANTS

OUT_DIR = RESULTS_ROOT / "thesis_v2" / "characterization"
FEATURE_DIR = pathlib.Path("results/thesis_v2/features")

SENSORS = ["pupil", "pupil_valid", "eda", "bvp", "speech"]


def _seconds_present(sample_index: pd.DatetimeIndex, grid: pd.DatetimeIndex) -> float:
    """Fraction of `grid` seconds containing at least one raw sample."""
    if len(sample_index) == 0 or len(grid) == 0:
        return 0.0
    present = pd.Index(sample_index.floor("1s")).unique()
    return float(grid.isin(present).mean())


def _raw_second_index(pid: str, sensor: str) -> pd.DatetimeIndex:
    """Timestamps of raw samples for one sensor, or an empty index if unavailable."""
    try:
        if sensor == "pupil":
            return load_pupil(pid).index
        if sensor == "pupil_valid":
            df = load_pupil(pid)
            # The tracker's own per-eye validity flags, not our artifact rejection.
            flags = [c for c in ("valid_left", "valid_right") if c in df.columns]
            if not flags:
                return df.index
            return df.index[(df[flags] > 0).any(axis=1)]
        if sensor == "eda":
            return load_eda(pid).index
        if sensor == "bvp":
            return load_bvp(pid).index
        if sensor == "speech":
            # load_speech_audio returns a `utc` column, not a DatetimeIndex.
            return pd.DatetimeIndex(load_speech_audio(pid)["utc"].dropna())
    except (FileNotFoundError, KeyError, IndexError, ValueError) as e:
        print(f"    [{pid}/{sensor}] unavailable: {type(e).__name__}: {e}")
    return pd.DatetimeIndex([])


def _analysed_grid(pid: str, stream: str) -> pd.DatetimeIndex:
    """The seconds the experiments actually score: the annotation grid after
    build_features.py's pre-session trim. Taken from that stage's own cached
    parquet so the denominator is identical by construction, not re-derived."""
    cached = FEATURE_DIR / f"{pid}_{stream}.parquet"
    if cached.exists():
        idx = pd.read_parquet(cached).index
        return pd.DatetimeIndex(pd.to_datetime(idx, utc=True))
    loader = load_rcea_aligned if stream == "rcea" else load_retro_aligned
    try:
        return loader(pid).index
    except (FileNotFoundError, KeyError, ValueError) as e:
        print(f"    [{pid}/{stream}] no annotation: {type(e).__name__}: {e}")
        return pd.DatetimeIndex([])


def _effective_rate_hz(idx: pd.DatetimeIndex) -> float:
    """Median achieved sampling rate of the raw stream, in Hz."""
    if len(idx) < 2:
        return float("nan")
    dt = pd.Series(idx.sort_values()).diff().dt.total_seconds().median()
    return round(1.0 / dt, 2) if dt and dt > 0 else float("nan")


def _pupil_valid_sample_fraction(pid: str) -> float:
    """Fraction of raw pupil samples the tracker itself flagged valid."""
    try:
        df = load_pupil(pid)
    except (FileNotFoundError, KeyError, ValueError):
        return float("nan")
    flags = [c for c in ("valid_left", "valid_right") if c in df.columns]
    if not flags or df.empty:
        return float("nan")
    return round(float((df[flags] > 0).any(axis=1).mean()), 4)


def per_participant_table(pids_by_stream: dict) -> pd.DataFrame:
    rows = []
    for stream, pids in pids_by_stream.items():
        for pid in pids:
            grid = _analysed_grid(pid, stream)
            if len(grid) == 0:
                continue  # no usable annotation: not part of either cohort
            print(f"  {pid}/{stream}: {len(grid)} analysed seconds")
            rec = {"pid": pid, "stream": stream, "analysed_seconds": len(grid)}
            for sensor in SENSORS:
                idx = _raw_second_index(pid, sensor)
                rec[sensor] = round(_seconds_present(idx, grid), 4)
                if sensor != "pupil_valid":
                    rec[f"{sensor}_n_samples"] = int(len(idx))
                    rec[f"{sensor}_rate_hz"] = _effective_rate_hz(idx)
            rec["pupil_valid_sample_frac"] = _pupil_valid_sample_fraction(pid)
            rows.append(rec)
    return pd.DataFrame(rows)


def summarise(full: pd.DataFrame) -> pd.DataFrame:
    rows = []
    for stream in ["rcea", "retro"]:
        sub = full[full.stream == stream]
        if sub.empty:
            continue
        for sensor in SENSORS:
            cov = sub[sensor]
            rec = {
                "stream": stream,
                "sensor": sensor,
                "participants": len(sub),
                "zero_coverage": int((cov == 0).sum()),
                "mean_second_coverage": round(float(cov.mean()), 4),
                "min_second_coverage": round(float(cov.min()), 4),
                "max_second_coverage": round(float(cov.max()), 4),
            }
            rate_col = f"{sensor}_rate_hz"
            if rate_col in sub.columns:
                rec["median_rate_hz"] = round(float(sub[rate_col].median()), 2)
            rows.append(rec)
    return pd.DataFrame(rows)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--pids", nargs="*", default=None,
                    help="smoke-test on a subset (default: full cohort)")
    args = ap.parse_args()

    rcea = args.pids if args.pids else RCEA_PARTICIPANTS
    retro = args.pids if args.pids else RETRO_PARTICIPANTS
    pids_by_stream = {"rcea": rcea, "retro": retro}

    print(f"Computing raw per-second coverage "
          f"(rcea={len(rcea)} candidates, retro={len(retro)} candidates)")
    full = per_participant_table(pids_by_stream)
    if full.empty:
        raise SystemExit("no participant produced an annotation grid")

    OUT_DIR.mkdir(parents=True, exist_ok=True)
    full.to_csv(OUT_DIR / "raw_coverage_full.csv", index=False)
    summary = summarise(full)
    summary.to_csv(OUT_DIR / "raw_coverage_summary.csv", index=False)

    print("\n=== Per-participant (head) ===")
    print(full.head(10).to_string(index=False))
    print("\n=== Summary ===")
    print(summary.to_string(index=False))
    print(f"\nCohort: rcea={len(full[full.stream=='rcea'])}, "
          f"retro={len(full[full.stream=='retro'])} participant-streams with annotation")
    print(f"Wrote raw_coverage_full.csv, raw_coverage_summary.csv -> {OUT_DIR}")


if __name__ == "__main__":
    main()
